DO $seo$ DECLARE old_events jsonb;old_routes jsonb;deps jsonb;expected jsonb; BEGIN PERFORM set_config('lock_timeout','5s',true);
PERFORM 1 FROM tb_evento_corridas WHERE id_evento IN (37526) ORDER BY id_evento FOR UPDATE;
PERFORM 1 FROM tb_evento_corridas_percursos WHERE id_evento IN (37526) ORDER BY id_evento_percurso FOR UPDATE;
IF (SELECT count(*) FROM tb_evento_corridas_percursos WHERE id_evento IN (37526))<>2 THEN RAISE EXCEPTION 'Routes changed'; END IF;
