sh',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_percurso_migracoes_strava d WHERE id_evento IN ('37526')),'tb_leaderboard_percurso',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_percurso d WHERE id_evento IN ('37526')),'tb_resultados_resumo',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_resumo d WHERE id_evento IN ('37526')),'tb_inscricoes',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_inscricoes d WHERE id_evento IN ('37526')))) IS DISTINCT FROM deps THEN RAISE EXCEPTION 'Dependencies changed'; END IF; END $seo$